{
 "$schema": "https://json-schema.org/draft/2020-12/schema",
 "$id": "urn:semantic-schema-core:semantic-abstract-schema:v1",
 "$vocabulary": {
  "https://json-schema.org/draft/2020-12/vocab/core": true,
  "https://json-schema.org/draft/2020-12/vocab/applicator": true,
  "https://json-schema.org/draft/2020-12/vocab/unevaluated": true,
  "https://json-schema.org/draft/2020-12/vocab/validation": true,
  "https://json-schema.org/draft/2020-12/vocab/meta-data": true,
  "https://json-schema.org/draft/2020-12/vocab/format-annotation": true,
  "https://json-schema.org/draft/2020-12/vocab/content": true,
  "urn:semantic-schema-core:vocab:v1": true
 },
 "title": "Semantic Abstract Schema v1 の本体",
 "description": "Semantic Concrete Schema が従う契約の版 v1。Concrete は $schema にこの $id を書いて、使う版と作法の版を示す。Concrete が足す x- は x-definitions に作法どおりに定義する。x-relationship と判定する者の形は annotations が、x-prompt ・ x-derive ・ x-view ・ rule の形はこの本体の $defs が持つ。",
 "allOf": [
  {
   "$ref": "https://json-schema.org/draft/2020-12/schema"
  }
 ],
 "x-prompt": {
  "read": {
   "means": "Concrete を書く人が従う契約で、従っていれば基盤が中身を知らずに使える。",
   "when": "Concrete を書く前と、Concrete を照らした指摘を直すときに読む。"
  },
  "write": [
   {
    "id": "generates-kind",
    "rule": "インスタンスを作るスキーマには x-generates を書き、根の properties に kind（const）を置く。",
    "why": "基盤は kind でインスタンスの種類を判定し、描画のしかたを選ぶ。",
    "test": "x-generates を持つスキーマの根に、kind の const があるかを見る。",
    "by": "machine"
   },
   {
    "id": "generates-schema-name",
    "rule": "インスタンスを作るスキーマは、根の properties に $schema を置き、const にこのスキーマの $id を書く。",
    "why": "インスタンスの $schema に、このスキーマの名前以外が書かれるのを、書いたその場で止める。",
    "test": "properties.$schema.const が $id と同じかを見る。",
    "by": "core"
   },
   {
    "id": "prompt-per-unit",
    "rule": "書く単位（最上位のプロパティと、$defs の各形のプロパティ）ごとに description と x-prompt を書く。",
    "why": "Scaffold は、書く単位ごとの x-prompt を返す。",
    "test": "書く単位のどれにも description と x-prompt があるかを見る。",
    "by": "machine"
   },
   {
    "id": "no-prompt-on-leaf",
    "rule": "入れ子の奥の葉には x-prompt を書かない。",
    "why": "親の x-prompt が葉まで案内するので、葉にも書くと同じ決まりが2か所に並ぶ。",
    "test": "x-prompt を持つ葉の親が、同じ決まりを持っていないかを見る。",
    "by": "ai",
    "bad": "verification.passed[].option に x-prompt を書く。",
    "good": "verification.passed の x-prompt に、option の書き方も書く。"
   },
   {
    "id": "list-as-array",
    "rule": "並びになる値は、文字列に詰めず配列の型にする。",
    "why": "型で配列にしておけば、インスタンスを書く人が文字列に詰めることができない。",
    "test": "区切りの記号で並びを書かせる文字列の欄が無いかを見る。",
    "by": "ai"
   },
   {
    "id": "core-keywords-closed",
    "rule": "x- で始まるキーは、Core の x- か、このスキーマの x-definitions にある名前だけを使う。",
    "why": "知らない x- を通すと、検証されない宣言が合格に見える。",
    "test": "x- で始まるキーが、Core の x- の定義か x-definitions にあるかを見る。",
    "by": "core"
   },
   {
    "id": "term-by-ref",
    "rule": "欄が glossary の term を指すときは、標準の $ref で glossary の URN と $anchor を指す。",
    "why": "Semantic Schema Resolver は、$ref の指す先から欄の term を静的にたどる。",
    "test": "term を指す $ref の先が、閉じた一覧の glossary の $anchor かを見る。",
    "by": "core"
   },
   {
    "id": "rule-validator",
    "rule": "意味の判断が要る決まりには by を書き、必要なら requires と required も書く。",
    "why": "基盤は by で validator を選ぶ。by の無い rule は unsupported と返る。",
    "test": "test を確かめるのに意味の判断が要る決まりに、by があるかを見る。",
    "by": "ai"
   }
  ]
 },
 "type": "object",
 "required": [
  "$schema",
  "title",
  "description"
 ],
 "properties": {
  "$schema": {
   "type": "string",
   "format": "uri",
   "description": "従う Abstract の版",
   "x-prompt": {
    "read": {
     "means": "このスキーマが従う Abstract の版と作法の版で、閉じた一覧のどれかである。"
    },
    "write": [
     {
      "id": "closed-list",
      "rule": "Abstract の版の $id を書く。",
      "why": "基盤は閉じた一覧に無い $schema を取りに行かずに断る。",
      "test": "値が閉じた一覧のどれかと同じかを見る。",
      "by": "core"
     }
    ]
   }
  },
  "$id": {
   "type": "string",
   "pattern": "^urn:[a-z0-9][a-z0-9-]*:[a-z0-9][a-z0-9-]*:v[0-9]+$",
   "description": "スキーマの名前",
   "x-prompt": {
    "read": {
     "means": "インスタンスが $schema で指す、このスキーマの名前である。",
     "parse": "urn:<Skill か Agent の名前>:<種類>:v<版> の形で、版は v と数字である。"
    },
    "write": [
     {
      "id": "context-kind-version",
      "rule": "urn:<Skill か Agent の名前>:<種類>:v<版> の形で書く。",
      "why": "Semantic Schema Resolver は、Skill と Agent の置き場所から、この名前でスキーマを引く。",
      "test": "名前空間が、このスキーマを持つ Skill か Agent のフォルダの名前かを見る。",
      "by": "core"
     },
     {
      "id": "never-reuse",
      "rule": "公開した版の中身を変えるときは、版を上げた新しい名前で足す。",
      "why": "同じ名前で中身が変わると、前に書いたインスタンスが別のスキーマで検査される。",
      "test": "公開した版の名前の中身が、公開した時と同じかを見る。",
      "by": "core"
     }
    ]
   }
  },
  "title": {
   "type": "string",
   "minLength": 1,
   "description": "スキーマの名前",
   "x-prompt": {
    "read": {
     "means": "このスキーマが表すものの名前である。",
     "shown": "描画したページの題と、Concrete を照らした結果に出る。"
    },
    "write": [
     {
      "id": "noun",
      "rule": "インスタンスが何であるかを、名詞で書く。",
      "why": "読む人は題だけで、何のインスタンスかを判断する。",
      "test": "題が名詞で終わっているかを見る。",
      "by": "ai",
      "bad": "意思決定を記録するためのもの",
      "good": "意思決定の記録"
     }
    ]
   }
  },
  "description": {
   "type": "string",
   "minLength": 1,
   "description": "スキーマの説明",
   "x-prompt": {
    "read": {
     "means": "インスタンスが何で、何を書かないかの説明である。"
    },
    "write": [
     {
      "id": "what-and-not",
      "rule": "インスタンスが何であるかと、書かないもの（ほかのスキーマが持つもの）を書く。",
      "why": "書かないものが分からないと、ほかのスキーマと同じことを2か所に書く。",
      "test": "説明に、書かないものが1つ以上あるかを見る。",
      "by": "ai"
     }
    ]
   }
  },
  "x-generates": {
   "type": "string",
   "minLength": 1,
   "description": "このスキーマが作るインスタンスの置き場所",
   "x-prompt": {
    "read": {
     "means": "このスキーマのインスタンスが作られる置き場所である。",
     "parse": "<…> の部分は、番号や名前が入る場所である。"
    },
    "write": [
     {
      "id": "placeholder",
      "rule": "番号や名前の部分を <…> にして、インスタンスのファイルの置き場所を書く。",
      "why": "読む人とツールが、同じ置き場所に作る。",
      "test": "<…> 以外の部分が、実際の置き場所と同じかを見る。",
      "by": "core"
     },
     {
      "id": "only-for-instances",
      "rule": "インスタンスを作らない部品のスキーマには書かない。",
      "why": "書くと、作られないインスタンスの kind を探すことになる。",
      "test": "$defs だけを持つスキーマに x-generates が無いかを見る。",
      "by": "core"
     }
    ]
   }
  },
  "x-definitions": {
   "type": "object",
   "description": "Concrete が足す x- の定義（作法の1）",
   "propertyNames": {
    "pattern": "^x-[a-z0-9-]+$"
   },
   "additionalProperties": {
    "type": "object",
    "required": [
     "schema",
     "description",
     "x-prompt"
    ],
    "additionalProperties": false,
    "properties": {
     "schema": {
      "$ref": "https://json-schema.org/draft/2020-12/schema",
      "description": "x- の値の形（JSON Schema）"
     },
     "description": {
      "type": "string",
      "minLength": 1
     },
     "x-prompt": {
      "$ref": "#/$defs/prompt"
     },
     "validator": {
      "$ref": "urn:semantic-schema-core:annotations:v1#/$defs/judge",
      "description": "任せる検証役の種類。名前は x-validators に書く。書かなければ、この x- の検証結果は unsupported になる"
     }
    }
   },
   "x-prompt": {
    "read": {
     "means": "このスキーマが足した x- の、値の形 ・ 意味 ・ 任せる検証役である。"
    },
    "write": [
     {
      "id": "no-core-names",
      "rule": "Core の x- と同じ名前を使わない。",
      "why": "Core の x- とぶつかると、どちらの意味で読むかが決まらない。",
      "test": "名前が Core の x- の定義と重なっていないかを見る。",
      "by": "core"
     }
    ]
   }
  },
  "x-validators": {
   "type": "object",
   "description": "validator の割り当て。rule の id か x- の名前ごとに、validator の名前を書く",
   "additionalProperties": {
    "type": "string",
    "minLength": 1
   },
   "x-prompt": {
    "read": {
     "means": "by が tool か ai の rule と x- を、どの validator が検証するかの対応である。"
    },
    "write": [
     {
      "id": "every-delegated",
      "rule": "by が tool か ai の rule と、validator を持つ x- のそれぞれに、validator の名前を書く。AI はモデルの名前まで書く。",
      "why": "割り当てが無いと、基盤は呼ぶ validator を決められず unsupported と返す。",
      "test": "by が tool か ai の rule の id が、ここにあるかを見る。",
      "by": "core"
     }
    ]
   }
  },
  "x-prompt": {
   "$ref": "#/$defs/prompt"
  },
  "properties": {
   "$ref": "#/$defs/fields"
  },
  "$defs": {
   "type": "object",
   "additionalProperties": {
    "$ref": "#/$defs/shape"
   }
  }
 },
 "if": {
  "required": [
   "x-generates"
  ]
 },
 "then": {
  "required": [
   "properties",
   "$id"
  ],
  "properties": {
   "properties": {
    "required": [
     "kind",
     "$schema"
    ],
    "properties": {
     "kind": {
      "required": [
       "const"
      ]
     },
     "$schema": {
      "required": [
       "const"
      ]
     }
    }
   }
  }
 },
 "$defs": {
  "shape": {
   "type": "object",
   "description": "$defs の形1つ。プロパティを持つなら、その書く単位に説明と案内を求める",
   "properties": {
    "properties": {
     "$ref": "#/$defs/fields"
    },
    "x-view": {
     "$ref": "#/$defs/view"
    }
   }
  },
  "fields": {
   "type": "object",
   "description": "書く単位の並び",
   "properties": {
    "$schema": true
   },
   "additionalProperties": {
    "$ref": "#/$defs/field"
   }
  },
  "field": {
   "type": "object",
   "description": "書く単位1つ。x-relationship の形は annotations が、x-derive と x-view の形はこの本体の $defs が持つ",
   "required": [
    "description",
    "x-prompt"
   ],
   "properties": {
    "description": {
     "type": "string",
     "minLength": 1
    },
    "x-prompt": {
     "$ref": "#/$defs/prompt"
    },
    "x-relationship": {
     "$ref": "urn:semantic-schema-core:annotations:v1#/$defs/relationship"
    },
    "x-derive": {
     "$ref": "#/$defs/derive"
    },
    "x-view": {
     "$ref": "#/$defs/view"
    }
   }
  },
  "derive": {
   "type": "object",
   "description": "x-derive。オブジェクトの答えから、決まりに従って値を導く。declared があれば宣言した値と比べ、expect があればほかの場所との組み合わせを確かめる",
   "required": [
    "rules",
    "otherwise"
   ],
   "additionalProperties": false,
   "properties": {
    "title": {
     "type": "string",
     "minLength": 1,
     "description": "導出値の見出し。検査には使わない"
    },
    "rules": {
     "type": "array",
     "minItems": 1,
     "description": "上から当て、最初に当たった決まりの then が導出値になる",
     "items": {
      "type": "object",
      "required": [
       "when",
       "then"
      ],
      "additionalProperties": false,
      "properties": {
       "when": {
        "type": "object",
        "minProperties": 1
       },
       "then": {
        "type": [
         "string",
         "number",
         "boolean"
        ]
       }
      }
     }
    },
    "otherwise": {
     "type": [
      "string",
      "number",
      "boolean"
     ],
     "description": "どの決まりにも当たらないときの導出値"
    },
    "declared": {
     "type": "string",
     "minLength": 1,
     "description": "導出値と比べる、同じオブジェクトの中のプロパティの名前"
    },
    "expect": {
     "type": "array",
     "description": "インスタンスのほかの場所の値との組み合わせの決まり"
    }
   },
   "x-prompt": {
    "read": {
     "means": "オブジェクトの答えから値を導く決まりである。",
     "parse": "rules を上から見て最初に当たった then を導出値とし、どれにも当たらなければ otherwise を導出値とする。"
    },
    "write": [
     {
      "id": "only-mechanical",
      "rule": "オブジェクトの中の答えから、別の値を機械的に決める決まりがあるときに書く。",
      "why": "人の判断が入る値は、決まりで導けない。",
      "test": "答えの組み合わせから、値が1つに決まるかを見る。",
      "by": "ai"
     }
    ]
   }
  },
  "view": {
   "type": "object",
   "description": "x-view。値を人が読む文にする型と、参照されたときの名前。text ・ cases ・ parts ・ maps ・ label ・ hidden を持つ",
   "additionalProperties": false,
   "dependentSchemas": {
    "hidden": {
     "maxProperties": 1
    }
   },
   "properties": {
    "text": {
     "type": "string",
     "description": "どの cases にも当たらないときの文の型。{…} の中は JMESPath 式"
    },
    "cases": {
     "type": "array",
     "minItems": 1,
     "description": "値によって言い方を変える。上から当て、最初に当たった text を使う"
    },
    "parts": {
     "type": "object",
     "description": "名前を付けた部分の文の型"
    },
    "maps": {
     "type": "object",
     "description": "値を文の中の語へ言い換える表"
    },
    "label": {
     "type": "string",
     "minLength": 1,
     "description": "この形の値が参照されたときに、名前として出す JMESPath 式"
    },
    "hidden": {
     "const": true,
     "description": "描画に出さない。ほかのキーと一緒に書かない"
    }
   },
   "x-prompt": {
    "read": {
     "means": "1つの形の値を、文にするか、名前として出すか、出さないかの決まりである。"
    },
    "write": [
     {
      "id": "hidden-alone",
      "rule": "描画に出さないなら、hidden: true だけを書く。",
      "why": "ほかのキーと一緒に書くと、出すのか出さないのかが決まらない。",
      "test": "hidden がある x-view に、ほかのキーが無いかを見る。",
      "by": "machine"
     }
    ]
   }
  },
  "prompt": {
   "type": "object",
   "description": "x-prompt。read は値の読み方を観点ごとに、write は書くときの決まりを1件ずつ持つ",
   "required": [
    "read",
    "write"
   ],
   "additionalProperties": false,
   "properties": {
    "read": {
     "$ref": "#/$defs/reading"
    },
    "write": {
     "type": "array",
     "minItems": 1,
     "items": {
      "$ref": "#/$defs/rule"
     }
    }
   }
  },
  "reading": {
   "type": "object",
   "description": "値の読み方。観点ごとに1文",
   "required": [
    "means"
   ],
   "additionalProperties": false,
   "properties": {
    "means": {
     "$ref": "#/$defs/sentence",
     "description": "何を表すか"
    },
    "shown": {
     "$ref": "#/$defs/sentence",
     "description": "どこにどう出るか"
    },
    "parse": {
     "$ref": "#/$defs/sentence",
     "description": "値をどう解くか"
    },
    "when": {
     "$ref": "#/$defs/sentence",
     "description": "いつ、何のために読むか"
    }
   }
  },
  "rule": {
   "type": "object",
   "description": "書くときの決まり1件",
   "required": [
    "id",
    "rule",
    "why",
    "test"
   ],
   "additionalProperties": false,
   "properties": {
    "id": {
     "type": "string",
     "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$"
    },
    "rule": {
     "$ref": "#/$defs/sentence"
    },
    "why": {
     "$ref": "#/$defs/sentence"
    },
    "test": {
     "$ref": "#/$defs/sentence"
    },
    "by": {
     "$ref": "urn:semantic-schema-core:annotations:v1#/$defs/judge",
     "description": "この決まりを判定する者。書かなければ unsupported と返る"
    },
    "requires": {
     "type": "array",
     "items": {
      "type": "string",
      "minLength": 1
     },
     "description": "validator に必要な capability"
    },
    "required": {
     "type": "boolean",
     "description": "検証できなければ全体を成功にしない決まりか"
    },
    "bad": {
     "type": "string",
     "minLength": 1
    },
    "good": {
     "type": "string",
     "minLength": 1
    }
   },
   "dependentRequired": {
    "bad": [
     "good"
    ],
    "good": [
     "bad"
    ]
   }
  },
  "sentence": {
   "type": "string",
   "minLength": 1,
   "maxLength": 120
  }
 }
}
